import net.officefloor.web.ObjectResponse;

public class RespondWithRates {
    public void respond(@Val List<Rate> rates, ObjectResponse<List<RateResponse>> response) {
        response.send(rates.stream().map(RateResponse::from).toList());
    }
}
package net.officefloor.hq.app.rate;

/** A rate as the screen shows it: the grade, the percent with two decimals the from-date (null: from the start) and the to-date (null: no end). */
public record RateResponse(String grade, String rate, String from, String to) {

    public static RateResponse from(Rate rate) {
        return new RateResponse(rate.grade(), rate.rate().setScale(2).toPlainString(),
                rate.from() == null ? null : rate.from().toString(),
                rate.to() == null ? null : rate.to().toString());
    }
}

